tool_args.command:
python3 -c "
import json
valid_et = {'Task','Method','Material','Metric','OtherScientificTerm','Generic'}
valid_rt = {'Used-for','Feature-of','Hyponym-of','Part-of','Compare','Conjunction','Evaluate-for'}
dr_map = json.load(open('/root/schema_semantic_constrained_ie/ontology_constraints.json'))
dr_lookup = {}
for r in dr_map.get('relations',[]):
    rn = r['name']
    for p in r.get('valid_pairs',[]):
        dr_lookup.setdefault(rn,set()).add((p['head'],p['tail']))
et_v=rv_v=dr_v=cf_v=0
total_r=total_e=0
parse_fail=0
dr_by_rel={}
with open('/root/schema_semantic_constrained_ie/outputs/w5_lora_scierc_full_s1_eval.jsonl') as f:
    for line in f:
        d=json.loads(line)
        p=d.get('parsed_output',{})
        if not p:
            parse_fail+=1
            continue
        ents=p.get('entities',[])
        rels=p.get('relations',[])
        total_e+=len(ents)
        total_r+=len(rels)
        ent_types={e['text']:e['type'] for e in ents}
        for e in ents:
            if e['type'] not in valid_et:
                et_v+=1
        for r in rels:
            if r['type'] not in valid_rt:
                rv_v+=1
                continue
            pair=(r.get('head_type',''),r.get('tail_type',''))
            rn=r['type']
            if rn in dr_lookup and pair not in dr_lookup[rn]:
                dr_v+=1
                dr_by_rel[rn]=dr_by_rel.get(rn,0)+1
print(f'Samples: 551, Parse fails: {parse_fail}')
print(f'Total entities: {total_e}, Total relations: {total_r}')
print(f'ET violations: {et_v} ({et_v/max(total_e,1)*100:.2f}%)')
print(f'RV violations: {rv_v} ({rv_v/max(total_r,1)*100:.2f}%)')
print(f'DR violations: {dr_v} ({dr_v/max(total_r,1)*100:.2f}%)')
print(f'DR by relation: {dr_by_rel}')
"
